use std::path::PathBuf;

async fn fetch_all<E>(a: PathBuf, b: PathBuf) -> Result<(Vec<u8>, Vec<u8>), E>
where
    E: From<std::io::Error> + Send,
{
    let fa = tokio::fs::read(a);
    let fb = tokio::fs::read(b);
    let (bytes_a, bytes_b) = tokio::try_join!(fa, fb)?;
    Ok((bytes_a, bytes_b))
}

use std::collections::HashMap;

#[derive(Debug)]
enum StoreError {
    NotFound,
}

trait JsonStore {
    type Error;
    fn get<'a>(&'a self, key: &str) -> Result<&'a [u8], Self::Error>;
    fn put(&mut self, key: String, val: Vec<u8>);
}

struct MemStore {
    inner: HashMap<String, Vec<u8>>,
}

impl JsonStore for MemStore {
    type Error = StoreError;

    fn get<'a>(&'a self, key: &str) -> Result<&'a [u8], Self::Error> {
        self.inner
            .get(key)
            .map(Vec::as_slice)
            .ok_or(StoreError::NotFound)
    }

    fn put(&mut self, key: String, val: Vec<u8>) {
        self.inner.insert(key, val);
    }
}

