use tokio_util::sync::CancellationToken;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Canceled;

async fn with_cancel<F>(fut: F, token: CancellationToken) -> Result<F::Output, Canceled>
where
    F: std::future::Future + Send + 'static,
{
    tokio::select! {
        output = fut => Ok(output),
        _ = token.cancelled() => Err(Canceled),
    }
}

from __future__ import annotations

from pathlib import Path

import pandas as pd

def merge_csv_dir(src: Path, dst: Path, chunksize: int = 100_000) -> None:
    files = sorted(src.glob("*.csv"))
    if not files:
        raise FileNotFoundError(src)
    dst.mkdir(parents=True, exist_ok=True)
    columns: list[str] | None = None
    for path in files:
        try:
            reader = pd.read_csv(path, chunksize=chunksize)
        except UnicodeDecodeError:
            reader = pd.read_csv(path, chunksize=chunksize, encoding="latin-1")
        for chunk in reader:
            chunk.columns = [str(c).strip().lower().replace(" ", "_") for c in chunk.columns]
            if "date" not in chunk.columns:
                raise KeyError(f"{path}: missing date column")
            if columns is None:
                columns = list(chunk.columns)
            chunk = chunk.reindex(columns=columns)
            chunk["date"] = pd.to_datetime(chunk["date"], utc=True, errors="coerce")
            chunk = chunk.dropna(subset=["date"])
            chunk["date"] = chunk["date"].dt.strftime("%Y-%m-%d")
            for day, part in chunk.groupby("date", sort=False):
                out = dst / f"date={day}"
                out.mkdir(parents=True, exist_ok=True)
                target = out / "part.parquet"
                piece = part.drop(columns=["date"])
                if target.exists():
                    prev = pd.read_parquet(target)
                    piece = pd.concat([prev, piece], ignore_index=True)
                piece.to_parquet(target, engine="pyarrow", index=False)

#!/usr/bin/env bash
set -euo pipefail

file_size() {
  local p=$1
  if [[ $(uname -s) == Darwin ]]; then
    stat -f %z -- "$p"
  else
    stat -c %s -- "$p"
  fi
}

build_manifest() {
  local root=$1 out=$2 tmp
  tmp=$(mktemp)
  find "$root" -type f -print0 |
    while IFS= read -r -d '' p; do
      local sum sz b64
      sum=$(shasum -a 256 -- "$p" | awk '{print $1}')
      sz=$(file_size "$p")
      b64=$(printf '%s' "$p" | base64 | tr -d '\n')
      printf '%s %s %s\n' "$sum" "$sz" "$b64"
    done | sort -k3,3 > "$tmp"
  mv -f "$tmp" "$out"
}

diff_manifests() {
  local old=$1 new=$2
  awk '
    FNR==NR { old[$3]=$1; next }
    {
      if (!($3 in old)) { print "added", $3; next }
      if (old[$3] != $1) print "changed", $3
      seen[$3]=1
    }
    END {
      for (p in old) if (!(p in seen)) print "removed", p
    }
  ' "$old" "$new" | while read -r kind b64; do
    path=$(printf '%s' "$b64" | base64 --decode 2>/dev/null || printf '%s' "$b64" | base64 -D)
    printf '%s %s\n' "$kind" "$path"
  done
}
